'use strict';
const $=s=>document.querySelector(s), esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const now=new Date(), fmt=d=>`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`, today=fmt(now), base=today.slice(0,7);
let state;try{state=JSON.parse(localStorage.getItem('chagok-v1'))}catch{}
const defaults={records:[],likes:[],saved:[],comments:{},joined:[],hidden:[],announcements:[]};
state={...JSON.parse(JSON.stringify(defaults)),...(state&&Array.isArray(state.records)?state:{})};
if(!state.cleanStart){
 const removed=new Set(state.records.filter(r=>r.sample===true).map(r=>r.id));
 ['p1','p2','p3','t1','t2','t3'].forEach(id=>removed.add(id));
 state.records=state.records.filter(r=>r.sample!==true);
 for(const key of ['likes','saved','hidden'])state[key]=state[key].filter(id=>!removed.has(id));
 for(const id of removed)delete state.comments[id];
 state.joined=state.joined.filter(id=>!['e1','e2'].includes(id));
 state.cleanStart=true;
 try{localStorage.setItem('chagok-v1',JSON.stringify(state))}catch{}
}
let storageKey='chagok-v1', currentUser=null;
let page='calendar',month=new Date(now.getFullYear(),now.getMonth(),1),selected=today,filter='전체';
function persist(){try{localStorage.setItem(storageKey,JSON.stringify(state));return true}catch{toast('저장 공간이 부족해요. 이번 변경은 화면에만 유지됩니다.');return false}}
function toast(t){$('#toast').textContent=t;$('#toast').classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').classList.remove('show'),3200)}
function chip(r){return `<span class="tea-chip ${r.type}">${esc(r.type)}</span>`}function head(title,sub,action=''){return `<div class="page-heading"><div><div class="eyebrow">CHAGOK · TEA JOURNAL</div><h1>${title}</h1><p class="sub">${sub}</p></div>${action}</div>`}
function openModal(title,body){$('#modal-body').innerHTML=`<div class="modal-head"><h2>${title}</h2><button aria-label="닫기" onclick="closeModal()">×</button></div>${body}`;if(!$('#modal').open)$('#modal').showModal()}
function closeModal(){$('#modal').close()}
function go(p){page=p;document.querySelectorAll('nav button').forEach(b=>b.classList.toggle('active',b.dataset.page===p));$('#breadcrumb').textContent='나의 찻자리 / '+({calendar:'내 차생활',feed:'차생활 둘러보기',talk:'이야기방',events:'이벤트',admin:'관리자 체험'}[p]);render()}
document.querySelectorAll('[data-page]').forEach(b=>b.addEventListener('click',()=>go(b.dataset.page)));$('.brand').onclick=()=>go('calendar');
function render(){({calendar:renderCalendar,feed:renderFeed,talk:renderTalk,events:renderEvents,admin:renderAdmin}[page]||renderCalendar)();if(page!=='admin'&&state.announcements.length)$('#app').insertAdjacentHTML('afterbegin', '<div class="notice">공지 · '+state.announcements.map(esc).join(' · ')+'</div>')}
function renderCalendar(){const prefix=fmt(month).slice(0,7),records=state.records.filter(r=>r.date.startsWith(prefix));const count={};records.forEach(r=>count[r.type]=(count[r.type]||0)+1);const favorite=Object.keys(count).sort((a,b)=>count[b]-count[a])[0]||'—';const first=new Date(month);first.setDate(1-first.getDay());let cells='';for(let i=0;i<42;i++){const d=new Date(first);d.setDate(first.getDate()+i);const date=fmt(d),rs=state.records.filter(r=>r.date===date);cells+=`<button class="day ${d.getMonth()!==month.getMonth()?'out':''} ${date===today?'today':''} ${date===selected?'selected':''}" aria-label="${date}, 기록 ${rs.length}개" aria-pressed="${date===selected}" onclick="selectDay('${date}')"><span class="day-number">${d.getDate()}</span>${rs.slice(0,2).map(r=>`<span class="tea-chip ${r.type}">${esc(r.name)}</span>`).join('')}${rs.length>2?`<span class="record-meta day-more">+${rs.length-2}</span>`:''}<span class="day-markers" aria-hidden="true">${[...new Set(rs.map(r=>r.type))].map(t=>`<i class="dot ${t}"></i>`).join('')}${rs.length?`<span>${rs.length}잔</span>`:''}</span></button>`}const dayRecords=state.records.filter(r=>r.date===selected);$('#app').innerHTML=head('내 차생활','한 잔의 차, 오래 기억하고 싶은 순간.',`<button class="primary" onclick="editRecord()">＋ 차 기록하기</button>`)+`<div class="stats"><div class="stat"><div><span class="stat-label">차와 함께한 날</span><strong>${new Set(records.map(r=>r.date)).size}<small>일</small></strong></div><span class="stat-icon">◷</span></div><div class="stat"><div><span class="stat-label">이번 달의 기록</span><strong>${records.length}<small>잔의 이야기</small></strong></div><span class="stat-icon">▤</span></div><div class="stat"><div><span class="stat-label">가장 자주 만난 차</span><strong style="font-size:20px">${favorite}</strong></div><span class="stat-icon">♧</span></div></div><div class="workspace"><div class="calendar-box"><div class="calendar-toolbar"><div class="month-nav"><strong>${month.getFullYear()}. ${String(month.getMonth()+1).padStart(2,'0')}</strong><button aria-label="이전 달" onclick="moveMonth(-1)">‹</button><button aria-label="다음 달" onclick="moveMonth(1)">›</button><button class="small-btn" style="font-size:11px;border:1px solid var(--line);padding:2px 8px" onclick="showToday()">오늘</button></div><div class="legend">${['보이차','우롱차','홍차'].map(t=>`<span><i class="dot ${t}"></i>${t}</span>`).join('')}</div></div><div class="week">${['일','월','화','수','목','금','토'].map(d=>`<span>${d}</span>`).join('')}</div><div class="grid">${cells}</div><p class="calendar-help">날짜를 선택해 그날의 차를 만나보세요.</p></div><aside class="day-panel" aria-label="선택한 날짜의 차 기록"><div class="date">${selected.replaceAll('-','. ')} ${selected===today?'· 오늘':''}</div><h2>이날의 찻자리</h2>${dayRecords.length?dayRecords.map(r=>`<article class="record">${chip(r)}<h3>${esc(r.name)}</h3><div class="record-meta">${esc(r.origin||'나의 찻자리')} · ${r.visibility==='private'?'나만 보기':'공개'}</div><p>${esc(r.note)}</p><button class="text-button" onclick="editRecord('${r.id}')">기록 자세히 보기 ↗</button></article>`).join(''):'<p class="empty">아직 기록이 없어요.<br>이날의 첫 잔을 남겨볼까요?</p>'}<button class="text-button" onclick="editRecord()">＋ 이 날짜에 기록 남기기</button></aside></div>`}
function selectDay(d){selected=d;renderCalendar()}
function moveMonth(n){month=new Date(month.getFullYear(),month.getMonth()+n,1);renderCalendar()}function showToday(){month=new Date(now.getFullYear(),now.getMonth(),1);selected=today;renderCalendar()}
function editRecord(id){if(globalThis.chagokAuth?.configured&&!globalThis.chagokAuth.ready){toast('로그인 상태를 확인하고 있어요. 잠시 후 다시 시도해주세요.');return;}const r=state.records.find(r=>r.id===id)||{date:selected,type:'우롱차',visibility:'private'};openModal(id?'차 기록 살펴보기':'오늘의 차를 기록해요',`<form id="record-form"><div class="form-row"><label class="field">마신 날짜<input name="date" type="date" value="${r.date}" required></label><label class="field">차 종류<select name="type">${['보이차','우롱차','홍차'].map(t=>`<option ${r.type===t?'selected':''}>${t}</option>`).join('')}</select></label></div><label class="field">차 이름<input name="name" placeholder="차 이름을 입력해주세요" maxlength="80" value="${esc(r.name||'')}" required></label><label class="field">오늘의 감상<textarea name="note" maxlength="3000" placeholder="향, 맛, 오늘의 기분. 편하게 남겨주세요.">${esc(r.note||'')}</textarea></label><details><summary>우리는 방법도 남기기</summary><div><label class="field">생산지 · 생산자<input name="origin" maxlength="100" value="${esc(r.origin||'')}" placeholder="생산지 또는 생산자"></label><div class="form-row"><label class="field">찻잎 (g)<input name="amount" type="number" min="0" max="1000" step="0.1" value="${esc(r.amount||'')}"></label><label class="field">물 (ml)<input name="water" type="number" min="0" max="10000" value="${esc(r.water||'')}"></label></div><label class="field">물 온도 (°C)<input name="temp" type="number" min="0" max="100" value="${esc(r.temp||'')}"></label></div></details><label class="field">공개 범위<select name="visibility"><option value="private" ${r.visibility==='private'?'selected':''}>나만 보기</option><option value="public" ${r.visibility==='public'?'selected':''}>전체 공개</option></select></label><div class="sub">보이차·우롱차·홍차를 기록해요. 가향차와 대용차는 다루지 않아요.</div><div class="form-actions">${id?`<button type="button" class="danger" onclick="deleteRecord('${id}')">삭제</button>`:''}<button type="button" class="small-btn" onclick="closeModal()">취소</button><button class="primary" type="submit">기록 저장</button></div></form>`);$('#record-form').onsubmit=e=>{e.preventDefault();const data=Object.fromEntries(new FormData(e.target));data.name=data.name.trim();if(!data.name)return toast('차 이름을 입력해주세요.');const record={...data,id:id||'r-'+crypto.randomUUID(),author:currentUser?.displayName||'나',sample:false};if(id)state.records=state.records.map(x=>x.id===id?record:x);else state.records.push(record);selected=data.date;month=new Date(data.date+'T12:00:00');month.setDate(1);const ok=persist();closeModal();render();if(ok)toast('차생활을 저장했어요.')}}
function deleteRecord(id){openModal('이 기록을 삭제할까요?',`<p class="sub">삭제한 기록은 되돌릴 수 없어요.</p><div class="form-actions"><button class="small-btn" onclick="editRecord('${id}')">돌아가기</button><button class="primary" onclick="confirmDelete('${id}')">삭제하기</button></div>`)}function confirmDelete(id){state.records=state.records.filter(r=>r.id!==id);persist();closeModal();render();toast('기록을 삭제했어요.')}
function posts(){return [...state.records.filter(r=>r.visibility==='public').map(r=>({...r,own:true}))].filter(r=>!state.hidden.includes(r.id))}
function renderFeed(){$('#app').innerHTML=head('차생활 둘러보기','서로의 찻자리에서 발견하는 새로운 취향.')+`<div class="filters">${['전체','보이차','우롱차','홍차','저장한 기록'].map(t=>`<button class="${filter===t?'active':''}" onclick="filter='${t}';renderFeed()">${t}</button>`).join('')}</div><div class="cards">${posts().filter(r=>filter==='전체'||r.type===filter||filter==='저장한 기록'&&state.saved.includes(r.id)).map(r=>`<article class="card"><div class="meta">${esc(r.author)} · ${r.date} </div>${chip(r)}<h2>${esc(r.name)}</h2><p>${esc(r.note)}</p><div class="card-actions"><button aria-label="공감" onclick="toggle('likes','${r.id}')">${state.likes.includes(r.id)?'♥':'♡'} ${state.likes.includes(r.id)?1:0}</button><button onclick="comments('${r.id}')">댓글 ${(state.comments[r.id]||[]).length}</button><button onclick="toggle('saved','${r.id}')">${state.saved.includes(r.id)?'저장됨':'저장'}</button></div></article>`).join('')||'<div class="empty">아직 해당하는 기록이 없어요.</div>'}</div>`}
function toggle(key,id){state[key]=state[key].includes(id)?state[key].filter(x=>x!==id):[...state[key],id];persist();renderFeed()}
function comments(id){const post=posts().find(r=>r.id===id);openModal(esc(post?.name||'이야기 나누기'),`<div>${(state.comments[id]||[]).map(c=>`<div class="comment"><b>나</b><br>${esc(c)}</div>`).join('')||'<p class="empty">첫 이야기를 남겨주세요.</p>'}</div><form id="comment-form"><label class="field">댓글<textarea name="comment" required maxlength="500" placeholder="이 찻자리에 한마디"></textarea></label><button class="primary">댓글 남기기</button></form>`);$('#comment-form').onsubmit=e=>{e.preventDefault();const c=new FormData(e.target).get('comment').trim();if(!c)return;state.comments[id]=[...(state.comments[id]||[]),c];persist();comments(id);render()}}
function renderTalk(){$('#app').innerHTML=head('이야기방','차를 마시며 궁금했던 것들, 함께 나눠요.')+'<div class="empty">아직 이야기가 없어요. 게시글 작성 기능을 준비하고 있습니다.</div>'}

function renderEvents(){$('#app').innerHTML=head('함께하는 찻자리','같은 시간, 서로 다른 잔에 담는 이야기.')+'<div class="empty">예정된 이벤트가 없어요. 새 찻자리가 열리면 이곳에서 안내할게요.</div>'}
function renderAdmin(){$('#app').innerHTML=head('관리자 체험','커뮤니티 운영 화면을 미리 살펴보세요.')+`<div class="notice">누구나 둘러볼 수 있는 시제품 화면입니다. 변경은 이 브라우저에만 적용되며, 실제 관리자 인증은 아직 연결되지 않았습니다.</div><h2 style="margin-bottom:15px">공지 관리</h2><form id="notice-form" class="list-item"><label class="field" style="flex:1;margin:0">공지 제목<input name="title" required maxlength="100" placeholder="새 소식을 입력해주세요"></label><button class="primary">공지 추가</button></form>${state.announcements.map((n,i)=>`<div class="list-item"><span>${esc(n)}</span><button class="danger" onclick="state.announcements.splice(${i},1);persist();renderAdmin()">삭제</button></div>`).join('')}<h2 style="margin:28px 0 15px">공개 기록 관리</h2>${[...state.records.filter(r=>r.visibility==='public')].map(r=>`<div class="list-item"><div><h3>${esc(r.name)}</h3><p>${esc(r.author)} · ${r.type}</p></div><button class="small-btn" onclick="moderate('${r.id}')">${state.hidden.includes(r.id)?'숨김 해제':'공개 피드에서 숨기기'}</button></div>`).join('')}`;$('#notice-form').onsubmit=e=>{e.preventDefault();const t=new FormData(e.target).get('title').trim();if(!t)return;state.announcements.push(t);persist();renderAdmin();toast('공지를 추가했어요.')}}
function moderate(id){state.hidden=state.hidden.includes(id)?state.hidden.filter(x=>x!==id):[...state.hidden,id];persist();renderAdmin()}
$('#login').onclick=()=>currentUser?showProfile():startGoogleLogin();
$('#profile').onclick=showProfile;
$('#modal').addEventListener('click',e=>{if(e.target===$('#modal')){const r=$('#modal').getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeModal()}});
if(document.modelContext?.registerTool){try{document.modelContext.registerTool({name:'start_tea_record',description:'Open the tea record form for a valid date; does not save a record.',inputSchema:{type:'object',properties:{date:{type:'string',pattern:'^\\d{4}-\\d{2}-\\d{2}$'}},required:['date'],additionalProperties:false},annotations:{readOnlyHint:false},execute(input){if(!/^\d{4}-\d{2}-\d{2}$/.test(input.date)||Number.isNaN(Date.parse(input.date))||new Date(input.date).toISOString().slice(0,10)!==input.date)throw new Error('Invalid date');selected=input.date;editRecord();return {opened:true,date:selected}}})}catch{}}
render();

function authMessage(code){return ({'app/not-configured':'구글 로그인 설정을 준비하고 있어요.','app/not-ready':'로그인 연결을 확인하고 있어요. 잠시 후 다시 시도해주세요.','app/https-required':'구글 로그인은 게시된 웹사이트에서 이용해주세요.','auth/popup-blocked':'브라우저에서 팝업을 허용한 뒤 다시 로그인해주세요.','auth/popup-closed-by-user':'로그인을 취소했어요.','auth/cancelled-popup-request':'이미 로그인 창이 열려 있어요.','auth/unauthorized-domain':'현재 사이트 주소의 로그인 허용 설정이 필요해요.','auth/operation-not-allowed':'구글 로그인 사용 설정이 필요해요.','auth/network-request-failed':'인터넷 연결을 확인하고 다시 시도해주세요.'})[code]||'로그인 연결에 실패했어요. 새로고침한 뒤 다시 시도해주세요.'}
function startGoogleLogin(){const a=globalThis.chagokAuth;if(!a?.configured){openModal('구글 로그인','<p>구글 로그인 설정을 준비하고 있어요.</p><p class="sub">현재는 로그인 없이 이 브라우저에 기록할 수 있어요.</p>');return;}if(a.error){toast(authMessage(a.error));return;}a.signIn().catch(e=>toast(authMessage(e.code)))}
function showProfile(){openModal('나의 찻자리','<p>'+esc(currentUser?.displayName||'방문자')+'</p>'+(currentUser?.email?'<p class="sub">'+esc(currentUser.email)+'</p>':'')+'<p class="sub">내 기록 '+state.records.length+'개 · 저장한 기록 '+state.saved.length+'개</p><div class="notice">기록은 이 브라우저에만 저장돼요. 로그인 전 기록과 계정별 기록은 따로 보관하며, 다른 기기로 자동 전송되지 않아요.</div><div class="form-actions"><button class="small-btn" onclick="closeModal();filter=&quot;저장한 기록&quot;;go(&quot;feed&quot;)">저장한 기록</button>'+(currentUser?'<button class="primary" onclick="logoutGoogle()">로그아웃</button>':'<button class="primary" onclick="closeModal();startGoogleLogin()">Google 로그인</button>')+'</div>')}
async function logoutGoogle(){try{await globalThis.chagokAuth.signOut();toast('로그아웃했어요.')}catch(e){toast(authMessage(e.code))}}
function updateAuthUI(){const a=globalThis.chagokAuth;const user=a?.user||null;const nextKey=user?'chagok-user-'+user.uid:'chagok-v1';if(nextKey!==storageKey){closeModal();storageKey=nextKey;let saved;try{saved=JSON.parse(localStorage.getItem(storageKey))}catch{}state=saved&&Array.isArray(saved.records)?{...JSON.parse(JSON.stringify(defaults)),...saved}:{...JSON.parse(JSON.stringify(defaults)),cleanStart:true};filter='전체';page='calendar';}currentUser=user;$('#login').textContent=user?'내 계정':a?.configured&&!a.ready?'로그인 확인 중…':'Google 로그인 ↗';$('#profile b').textContent=user?.displayName||'내 기록';$('#profile .avatar').textContent=(user?.displayName||'나').slice(0,1);$('#profile small').textContent=user?'계정별 기기 내 기록':'이 브라우저에 저장';if(a?.ready)go(page);}
if(typeof window!=='undefined'){window.addEventListener('chagok-auth-change',updateAuthUI);updateAuthUI();}


